const roomTextIndex=new Map();for(const pair of roomTextPairs)for(const value of pair)roomTextIndex.set(value,pair);
function roomTranslate(text){const raw=String(text),s=raw.trim(),pair=roomTextIndex.get(raw)||roomTextIndex.get(s);if(pair)return pair[roomLanguage==='zh'?0:1];let m;
 if(m=s.match(/^抽屉 (\d+) · 打开 \/ 收起$/))return roomLanguage==='en'?`Drawer ${m[1]} · Open / close`:s;
 if(m=s.match(/^简历 PDF 第 (\d+) 页，共 (\d+) 页$/))return roomLanguage==='en'?`Resume PDF page ${m[1]} of ${m[2]}`:s;
 for(const [prefix,en] of [['正在播放 · ','Now playing · '],['点击播放重试 · ','Click play to retry · '],['音量 / Volume · ','Volume · '],['已暂停背景音乐 · ','Background paused · ']])if(s.startsWith(prefix))return (roomLanguage==='en'?en:prefix.replace(' / Volume',''))+roomTranslate(s.slice(prefix.length));
 if(s.startsWith('添加'))return roomLanguage==='en'?'Add '+roomTranslate(s.slice(2)):s;
 if(s.startsWith('拖动贴纸 '))return roomLanguage==='en'?'Drag sticker '+s.slice(5):s;
 if(s.includes(' — ')&&/音频转码|提取音轨|截取音轨/.test(s)){const at=s.indexOf(' — ');let rest=s.slice(at);if(roomLanguage==='en')rest=rest.replace('音频转码为 MP3。','Audio transcoded to MP3.').replace('用户指定演奏，提取音轨并转码 MP3。','User-selected performance; audio extracted and transcoded to MP3.').replace('用户指定演奏，从原视频 1:53 截取音轨并转码 MP3。','User-selected performance; audio starts at 1:53, transcoded to MP3.');return roomTranslate(s.slice(0,at))+rest;}
 if(s.includes(' — Google Scholar 网页预览'))return roomTranslate(s.replace(' — Google Scholar 网页预览',''))+(roomLanguage==='en'?' — Google Scholar preview':' — 谷歌学术网页预览');
 if(s.startsWith('打开论文网页 / Open '))return (roomLanguage==='en'?'Open publication: ':'打开论文：')+roomTranslate(s.slice('打开论文网页 / Open '.length));
 if(s.endsWith(' 主页预览'))return roomLanguage==='en'?s.replace(' 主页预览',' homepage preview'):s;
 if(s.startsWith('打开 ')&&s.endsWith(' 原页面'))return roomLanguage==='en'?'Open '+s.slice(3,-4)+' original page':s;
 return raw;
}
const roomCanvasLabels=[];const roomCanvasFill=new WeakMap();
function roomLocalizeCanvas(c,w,h,draw){const ctx=c.getContext('2d');if(!roomCanvasFill.has(c))roomCanvasFill.set(c,ctx.fillText.bind(ctx));const fill=roomCanvasFill.get(c);ctx.fillText=(text,x,y,max)=>{const translated=roomTranslate(text);fill(translated,x,y,max??Math.max(20,w-24));};draw(ctx,w,h);}
