for(const d of [resumeDialog,pdfDialog,holodataDialog,linksDialog,publicationDialog]){const host=d.querySelector('header,.pdf-header,.detail-top');if(host)host.append(d.querySelector('.dialog-language'));}
 const compact=document.createElement('style');compact.textContent='dialog .dialog-language{white-space:nowrap;flex-shrink:0;min-width:64px!important;width:auto!important;font:14px Segoe UI,RoomChinese,sans-serif!important;margin:0 4px!important;position:static!important}#resume-reader header{display:grid;grid-template-columns:minmax(0,1fr) 70px 44px;gap:4px 8px}#resume-reader header strong{grid-column:1;grid-row:1}#resume-reader header .dialog-language{grid-column:2;grid-row:1}#resume-reader header button:not(.dialog-language){grid-column:3;grid-row:1}#resume-reader header a{grid-column:1/4;grid-row:2;min-height:32px}#resume-reader .resume-pages{height:calc(100% - 100px)}';document.head.append(compact);
 const sources=new WeakMap();let observer;
 function applyDom(){observer?.disconnect();const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const p=node.parentElement;if(!p||p.closest('script,style,textarea,.guest-entry,.experience-body,.memory-photo,#room-language,.dialog-language'))continue;const prev=sources.get(node);const original=prev&&node.nodeValue===prev.output?prev.original:node.nodeValue;const output=roomTranslate(original);sources.set(node,{original,output});if(node.nodeValue!==output)node.nodeValue=output;}
 for(const el of document.querySelectorAll('[aria-label],[placeholder],[title],[alt]')){if(el.closest('.guest-entry,.memory-photo,#room-language,.dialog-language'))continue;let state=sources.get(el)||{};for(const attr of ['aria-label','placeholder','title','alt']){if(!el.hasAttribute(attr))continue;const value=el.getAttribute(attr),prev=state[attr],original=prev&&prev.output===value?prev.original:value,output=roomTranslate(original);state[attr]={original,output};if(output!==value)el.setAttribute(attr,output);}sources.set(el,state);}
 observer?.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','placeholder','title','alt']});}
