function quiltPoint(u,v){const x=(u-.5)*2.36+.065*Math.sin(v*7),z=-1.36+v*3.98+.14*Math.sin(u*7+.2)*(1-v);const drape=Math.max(0,(Math.abs(x)-1.03)/.15);const foot=Math.max(0,(z-2.43)/.21);let y=1.175+.060*Math.sin(u*24+v*11)+.024*Math.sin(v*35-u*13)+.055*Math.sin(u*8+v*7);y-=.28*Math.pow(Math.min(1,drape),1.2)+.19*Math.min(1,foot);y+=.085*Math.exp(-Math.pow((v-.08)/.07,2));return[x,y,z];}
for(let i=0;i<qp.count;i++){const u=(i%75)/74,v=Math.floor(i/75)/100;const p=quiltPoint(u,v);qp.setXYZ(i,...p);}quiltGeometry.computeVertexNormals();
