let roomColliders=[],collisionReady=false,roomCollisionDirty=false,routeRetryAfter=0;const navigationCell=.22,navigationOrigin=-3.88,navigationSize=50;
function ancestorIs(o,root){for(let p=o;p;p=p.parent)if(p===root)return true;return false;}
function collisionVisible(o){for(let p=o;p;p=p.parent)if(!p.visible)return false;return true;}
function refreshRoomColliders(){scene.updateMatrixWorld(true);roomColliders=[];scene.traverse(o=>{if(!o.isMesh||!o.geometry||o.userData.renderBatch||ancestorIs(o,girl)||ancestorIs(o,bunny)||ancestorIs(o,sleepingShoes)||ancestorIs(o,trophyStep)||o.geometry.type==='PlaneGeometry'||!collisionVisible(o)||o.material?.opacity===0)return;o.geometry.computeBoundingBox();const bounds=o.geometry.boundingBox.clone().applyMatrix4(o.matrixWorld);o.userData.collisionBounds=bounds;if(bounds.max.y<.14||bounds.min.y>3.5||bounds.max.x< -4||bounds.min.x>6.9||bounds.max.z< -4||bounds.min.z>6.7)return;roomColliders.push({object:o,bounds});});collisionReady=true;roomCollisionDirty=false;}
function chairOverlap(){chair.updateWorldMatrix(true,true);const cb=new THREE.Box3().setFromObject(chair);let overlap=0;for(const c of roomColliders){if(ancestorIs(c.object,chair)||!cb.intersectsBox(c.bounds))continue;const a=cb.clone().intersect(c.bounds),size=a.getSize(new THREE.Vector3());overlap+=Math.max(0,size.x)*Math.max(0,size.y)*Math.max(0,size.z);}return overlap;}
const chairRugBounds={minX:-2.1,maxX:3.5,minZ:-2.6,maxZ:3.0},chairFootprint=.76;let chairDragPoint=null;const chairDragPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0),chairMoveRay=new THREE.Raycaster();
