function moveChairSafely(dx,dz){if(roomCollisionDirty)refreshRoomColliders();const start=chair.position.clone(),goal=new THREE.Vector3(THREE.MathUtils.clamp(start.x+dx,chairRugBounds.minX+chairFootprint,chairRugBounds.maxX-chairFootprint),start.y,THREE.MathUtils.clamp(start.z+dz,chairRugBounds.minZ+chairFootprint,chairRugBounds.maxZ-chairFootprint));let baseline=chairOverlap();const steps=Math.max(1,Math.ceil(start.distanceTo(goal)/.05));for(let i=1;i<=steps;i++){const previous=chair.position.clone();chair.position.lerpVectors(start,goal,i/steps);const newOverlap=chairOverlap();const occupiedByGirl=girlActivity==='computer'&&(girlPhase==='act'||girlPhase==='settle');const nearPerson=girl.visible&&!occupiedByGirl&&girlPhase!=='sleeping'&&girlPhase!=='bed'&&Math.hypot(chair.position.x-girl.position.x,chair.position.z-girl.position.z)<1.0;const nearRabbit=Math.hypot(chair.position.x-bunny.position.x,chair.position.z-bunny.position.z)<1.02;if(newOverlap>baseline+.0005||nearPerson||nearRabbit){chair.position.copy(previous);break;}baseline=newOverlap;}roomCollisionDirty=true;}
