if(girlPhase==='leave'){girlPoseBlend=Math.max(0,girlPoseBlend-dt/1.5);const k=1-girlPoseBlend;girl.position.lerpVectors(girlSettleFrom,station.approach,k*k*(3-2*k));if(girlPoseBlend===0){girlPhase='walk';const next=pendingGirlActivity||'reading';pendingGirlActivity=null;setGirlActivity(next);return;}}else if(girlPhase==='settle'){girlPoseBlend=Math.min(1,girlPoseBlend+dt/1.2);const t=girlPoseBlend*girlPoseBlend*(3-2*girlPoseBlend);girl.position.lerpVectors(girlSettleFrom,station.p,t);girl.rotation.y+=Math.atan2(Math.sin(station.angle-girl.rotation.y),Math.cos(station.angle-girl.rotation.y))*Math.min(1,dt*7);if(girlPoseBlend===1){girlPhase='act';girlElapsed=0;}}else{girlElapsed+=dt;girl.position.copy(station.p);girl.rotation.y=station.angle;}
const sleeping=false;sleepingHiddenParts.forEach(o=>o.visible=true);girlLegs.forEach(o=>o.hip.visible=true);trophyStep.visible=false;heldBook.visible=girlActivity==='reading';cleaningCloth.visible=girlActivity==='trophies';sleepingShoes.visible=sleeping;girlShoes.forEach(o=>o.visible=!sleeping);sleepLids.visible=sleeping;girlEyeParts.forEach((o,i)=>{o.visible=!sleeping;o.scale.copy(girlEyeScales[i]);});
if(girlActivity==='computer'||girlActivity==='piano'){hip=girlActivity==='computer'?-1.28:-Math.PI/2;knee=-hip;arm=girlActivity==='computer'?-1.60:-1.26;elbow=.12;lean=.04;}
