publicationDialog.querySelector('.detail-close').onclick=()=>publicationDialog.close();publicationDialog.addEventListener('click',e=>{const r=publicationDialog.getBoundingClientRect();if(e.target===publicationDialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))publicationDialog.close();});publicationDialog.addEventListener('close',()=>{document.body.style.cursor='grab';});

const sideScreenStyle=document.createElement('style');sideScreenStyle.textContent=`
#guestbook-reader,#links-reader{width:min(1060px,92vw);background:#faf5fb;border:8px solid #d9cedf;border-radius:22px}#guestbook-reader .detail-top,#links-reader .detail-top{background:#e9deee;color:#685471}.guestbook-layout{display:grid;grid-template-columns:1fr 1.15fr;gap:28px;padding:28px;max-height:70vh;overflow:auto}.guestbook-layout h2{font:27px 'RoomPaper',RoomChinese,cursive;margin:0 0 12px}.guestbook-layout label{display:block;margin:15px 0 6px;font-size:14px}.guestbook-layout input,.guestbook-layout textarea{box-sizing:border-box;width:100%;border:1px solid #d7c8dc;background:#fffcff;border-radius:12px;padding:12px;font:16px/1.6 inherit;color:#544660}.guestbook-layout textarea{min-height:145px;resize:vertical}.guestbook-layout button[type=submit],.link-action{display:inline-block;border:0;border-radius:20px;padding:10px 23px;background:#a888b7;color:white;text-decoration:none;cursor:pointer;margin-top:12px}.guestbook-note{font-size:13px;color:#927d9a}.guest-entry{background:#fff7e5;border-radius:7px 13px 9px 15px;padding:16px 19px;margin:0 0 16px;transform:rotate(-.5deg);overflow-wrap:anywhere}.guest-entry:nth-child(even){background:#e9eff7;transform:rotate(.6deg)}.guest-entry strong{font-family:'RoomPaper',RoomChinese,cursive}.guest-entry time{float:right;font-size:11px;color:#958599}.guest-entry p{white-space:pre-wrap;margin:8px 0 0}.guestbook-empty{padding:30px;color:#96819b;font-family:'RoomPaper',RoomChinese,cursive}.guest-status{min-height:25px;font-size:14px;color:#816487}.links-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;padding:30px}.link-card{border:1px solid #e7dbea;background:#fffbff;border-radius:20px;padding:24px 12px;color:#5b4966;cursor:pointer}.link-symbol{display:grid;place-items:center;margin:0 auto 12px;width:60px;height:60px;border-radius:18px;font:bold 30px Georgia;color:#fff}.link-card strong{font:20px 'RoomPaper',cursive}.link-card span:last-child{display:block;font-size:12px;margin-top:7px;color:#8f7e98}.resource-preview{max-height:70vh;overflow:auto;background:#fff}.resource-preview>a{display:block;cursor:pointer}.resource-preview img{width:100%;display:block}.resource-preview iframe{width:100%;height:68vh;border:0;display:block}.resource-caption{padding:10px 20px;color:#8b7995;font-size:13px;background:#f6eff7}.links-back{border:0;background:transparent;color:inherit;font:inherit;cursor:pointer}
@media(max-width:640px){.guestbook-layout{grid-template-columns:1fr;padding:18px}.links-grid{grid-template-columns:repeat(2,minmax(0,1fr));padding:15px;gap:12px}.link-card{padding:17px 8px}.link-card strong{font-size:17px}}
`;document.head.appendChild(sideScreenStyle);
const postcardStyle=document.createElement('style');postcardStyle.textContent=`
#guestbook-reader{width:min(1180px,94vw);border:1px solid #e1d5d9;background:#f0e8e2;border-radius:14px}#guestbook-reader .detail-top{background:#f9f3eb}.guestbook-layout{grid-template-columns:minmax(0,1.6fr) minmax(230px,1fr);gap:25px;padding:26px;max-height:78vh}.postcard-paper{position:relative;background:#fffaf0;padding:28px 24px 20px;box-shadow:0 8px 25px #68554618;min-width:0;border:8px solid #d9a9bc;border-radius:3px}.postcard-paper[data-border=airmail],.guest-entry[data-border=airmail]{border:8px solid transparent;border-image:repeating-linear-gradient(135deg,#9cb9d1 0 12px,#fffaf0 12px 24px,#d6a1ac 24px 36px,#fffaf0 36px 48px) 8}.postcard-paper[data-border=lace],.guest-entry[data-border=lace]{border:8px dotted #c0b3d5}.postcard-paper[data-border=flowers],.guest-entry[data-border=flowers]{border:8px double #a9ba9c;background-color:#fffaf0;background-image:radial-gradient(#ddb4ca 2px,transparent 3px);background-size:19px 19px;background-clip:padding-box}.postcard-paper h2{font:30px 'RoomPaper',RoomChinese,cursive;color:#8a667c;margin:0 0 20px}.postcard-stamp{float:right;border:2px dotted #b89daa;padding:9px;font-size:25px;transform:rotate(8deg)}.guestbook-layout .postcard-paper input,.guestbook-layout .postcard-paper textarea{background:#fffaf0b8;border:0;border-bottom:1px solid #d7c7bc;border-radius:0;padding:7px 0;color:#67515c;font:20px/1.8 'RoomPaper','RoomChinese',cursive;position:relative}.guestbook-layout .postcard-paper textarea{height:160px;min-height:130px;resize:vertical;line-height:32px;background:repeating-linear-gradient(transparent 0 31px,#d9d0c660 31px 32px);margin:14px 0 0}.postcard-paper label{font:14px 'RoomPaper',RoomChinese,cursive;color:#a18b8e;margin:8px 0}.drawing-wrap{position:relative;margin-top:14px;border:1px dashed #cdbcc9;background:#ffffff60}.drawing-wrap canvas{display:block;width:100%;height:auto;touch-action:none;cursor:crosshair}.drawing-label{font:14px 'RoomPaper',RoomChinese,cursive;color:#b09aa3;position:absolute;left:12px;top:8px;pointer-events:none}.sticker-layer{position:absolute;inset:0;pointer-events:none;overflow:hidden}.placed-sticker{position:absolute;pointer-events:auto;background:none;border:0;padding:0;font:38px 'Segoe UI Emoji';line-height:1.2;touch-action:none;cursor:grab;transform:translate(-50%,-50%) rotate(-9deg);filter:drop-shadow(0 2px 1px #96748530)}.placed-sticker:focus{outline:2px dashed #b58bc8;outline-offset:3px}.postcard-tools{margin:17px 0;font:13px 'Segoe UI',sans-serif;color:#7f697a;display:flex;flex-wrap:wrap;gap:8px;align-items:center}.postcard-tools button,.postcard-tools select{border:1px solid #d9cad4;border-radius:8px;background:#fffaf8;padding:7px 10px;color:#705b6e;cursor:pointer}.postcard-tools button[aria-pressed=true]{outline:2px solid #aa86b7}.postcard-tools .sticker-choice{font:26px 'Segoe UI Emoji';padding:4px 7px}.tool-label{width:100%;margin-top:6px}.guest-entry{font:17px/1.7 'RoomPaper',RoomChinese,cursive;border:6px solid #d9a9bc;background:#fffaf0!important;transform:rotate(-1deg);padding:17px}.guest-entry img{display:block;width:100%;margin-top:12px}.guest-entry p{overflow-wrap:anywhere}.guest-entry time{font:11px 'Segoe UI';float:none;display:block}.guestbook-note{margin:8px 0}.email-card{text-align:center;padding:65px 20px;font-family:'Segoe UI',sans-serif}.email-card h2{font-weight:500}#links-reader{border:1px solid #c4cee0;border-radius:8px;background:#e8edf7}#links-reader .detail-top{background:#f4f7fc;color:#38495e;font-family:'Segoe UI',sans-serif}.links-grid{min-height:360px;align-content:start;grid-template-columns:repeat(3,130px);gap:18px 14px;background:radial-gradient(ellipse at 80% 60%,#e3ddfb 0,#bad0f0 40%,#cedfed 75%);padding:35px}.link-card{background:transparent;border:1px solid transparent;border-radius:4px;padding:12px 5px;color:#33435d}.link-card:hover,.link-card:focus-visible{background:#ffffff55;border-color:#ffffffaa}.link-card strong{font:14px 'Segoe UI',sans-serif}.link-card span:last-child{display:none}.link-symbol{margin-bottom:8px;border-radius:0;width:48px;height:48px}#links-reader .links-content{overflow:auto;max-height:76vh}
#guestbook-reader .placed-sticker{font:38px/1.2 'Segoe UI Emoji';}#guestbook-reader #postcard-color{width:42px;height:34px;padding:3px;flex:0 0 42px;border-radius:6px}#guestbook-reader .sticker-choice{font:26px 'Segoe UI Emoji';}.links-grid{position:relative;padding-bottom:70px}.links-grid:after{content:'⊞     ⌕     📁     🌐';position:absolute;bottom:0;left:0;right:0;text-align:center;background:#edf3fae8;border-top:1px solid #ffffff99;padding:12px;color:#2876c5;font:21px 'Segoe UI',sans-serif;letter-spacing:6px}
@media(max-width:700px){.guestbook-layout{grid-template-columns:minmax(0,1fr);padding:12px}.postcard-paper{padding:18px 14px}.postcard-paper h2{font-size:23px}.links-grid{grid-template-columns:repeat(3,minmax(0,1fr));padding:15px;gap:8px}.guestbook-layout .postcard-paper textarea{font-size:18px}}
`;document.head.appendChild(postcardStyle);
const guestbookDialog=document.createElement('dialog');guestbookDialog.id='guestbook-reader';guestbookDialog.className='room-detail';guestbookDialog.setAttribute('aria-label','制作明信片');guestbookDialog.innerHTML=`<div class="detail-top"><span>A postcard for you ♡</span><button class="detail-close" aria-label="关闭明信片">×</button></div><div class="guestbook-layout"><form><div class="postcard-paper" data-border="airmail"><span class="postcard-stamp">🌷</span><h2>Hello, little world!</h2><label for="guest-name">From</label><input id="guest-name" maxlength="40" autocomplete="nickname" placeholder="签下你的名字…"><label for="guest-message">To Kino,</label><textarea id="guest-message" maxlength="1000" placeholder="想把今天的小美好告诉你…"></textarea><div class="drawing-wrap"><span class="drawing-label">在这里画一点小心情…</span><canvas id="postcard-drawing" width="680" height="270" aria-label="自由绘画区域"></canvas></div><div class="sticker-layer"></div></div><div class="postcard-tools"><span class="tool-label">画笔 · Draw a little happiness</span><input type="color" id="postcard-color" value="#9675af" aria-label="画笔颜色"><button type="button" id="draw-undo">撤销笔画</button><button type="button" id="draw-clear">清空画布</button><span class="tool-label">贴一枚小可爱 · 添加后可拖动，选中后可移除</span><div class="sticker-palette"></div><button type="button" id="sticker-remove">移除选中贴纸</button><label for="postcard-border">花边</label><select id="postcard-border"><option value="airmail">✉ 航空邮边</option><option value="lace">♡ 点点蕾丝</option><option value="flowers">❀ 花园花边</option><option value="pink">粉色相框</option></select></div><button type="submit">收藏这张明信片 ♡</button><p class="guestbook-note">仅保存在当前浏览器，本机可见。</p><p class="guest-status" role="status" aria-live="polite"></p></form><section class="guest-messages" aria-label="收藏的明信片"></section></div>`;document.body.appendChild(guestbookDialog);
const guestbookKey='kino-study-guestbook-v1';let guestMessages=[];
const postcardCanvas=guestbookDialog.querySelector('canvas'),postcardCtx=postcardCanvas.getContext('2d'),postcardPaper=guestbookDialog.querySelector('.postcard-paper'),stickerLayer=guestbookDialog.querySelector('.sticker-layer');let postcardStrokes=[],drawingStroke=null,postcardStickers=[],selectedSticker=null;
function redrawPostcard(){postcardCtx.clearRect(0,0,680,270);for(const s of postcardStrokes){postcardCtx.strokeStyle=s.color;postcardCtx.fillStyle=s.color;postcardCtx.lineWidth=3;postcardCtx.lineCap='round';postcardCtx.lineJoin='round';postcardCtx.beginPath();s.points.forEach(([x,y],i)=>i?postcardCtx.lineTo(x,y):postcardCtx.moveTo(x,y));postcardCtx.stroke();if(s.points.length===1){postcardCtx.beginPath();postcardCtx.arc(...s.points[0],1.5,0,7);postcardCtx.fill();}}guestbookDialog.querySelector('.drawing-label').hidden=postcardStrokes.length>0;}
function drawingPoint(e){const r=postcardCanvas.getBoundingClientRect();return[(e.clientX-r.left)*680/r.width,(e.clientY-r.top)*270/r.height];}
postcardCanvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();drawingStroke={color:guestbookDialog.querySelector('#postcard-color').value,points:[drawingPoint(e)]};postcardStrokes.push(drawingStroke);postcardCanvas.setPointerCapture(e.pointerId);redrawPostcard();});postcardCanvas.addEventListener('pointermove',e=>{if(!drawingStroke)return;drawingStroke.points.push(drawingPoint(e));redrawPostcard();});for(const type of ['pointerup','pointercancel','lostpointercapture'])postcardCanvas.addEventListener(type,()=>drawingStroke=null);
guestbookDialog.querySelector('#draw-undo').onclick=()=>{postcardStrokes.pop();redrawPostcard();};guestbookDialog.querySelector('#draw-clear').onclick=()=>{postcardStrokes=[];redrawPostcard();};guestbookDialog.querySelector('#postcard-border').onchange=e=>postcardPaper.dataset.border=e.target.value;
function addPostcardSticker(symbol){if(postcardStickers.length>=24)return;const item={symbol,x:72,y:32};postcardStickers.push(item);const el=document.createElement('button');el.type='button';el.className='placed-sticker';el.textContent=symbol;el.setAttribute('aria-label','拖动贴纸 '+symbol);item.el=el;const position=()=>{el.style.left=item.x+'%';el.style.top=item.y+'%';};position();let drag=null;el.onpointerdown=e=>{e.preventDefault();selectedSticker=item;el.focus();drag=e.pointerId;el.setPointerCapture(e.pointerId);};el.onpointermove=e=>{if(drag!==e.pointerId)return;const r=stickerLayer.getBoundingClientRect();item.x=Math.max(5,Math.min(95,(e.clientX-r.left)/r.width*100));item.y=Math.max(5,Math.min(95,(e.clientY-r.top)/r.height*100));position();};el.onpointerup=el.onpointercancel=()=>drag=null;el.onfocus=()=>selectedSticker=item;stickerLayer.append(el);selectedSticker=item;}
for(const [symbol,name] of [['👼','小天使'],['🐰','小兔子'],['🌼','雏菊'],['🎀','蝴蝶结'],['🦋','蝴蝶'],['💗','爱心'],['✨','星光'],['☁️','云朵']]){const b=document.createElement('button');b.type='button';b.className='sticker-choice';b.textContent=symbol;b.title=name;b.setAttribute('aria-label','添加'+name);b.onclick=()=>addPostcardSticker(symbol);guestbookDialog.querySelector('.sticker-palette').append(b);}
guestbookDialog.querySelector('#sticker-remove').onclick=()=>{if(!selectedSticker)return;selectedSticker.el.remove();postcardStickers=postcardStickers.filter(s=>s!==selectedSticker);selectedSticker=null;};
function loadGuestbook(){try{const parsed=JSON.parse(localStorage.getItem(guestbookKey)||'[]');guestMessages=Array.isArray(parsed)?parsed.filter(m=>m&&typeof m.text==='string'&&typeof m.name==='string').slice(-100):[];}catch{guestMessages=[];}}
function renderGuestbook(){const list=guestbookDialog.querySelector('.guest-messages');list.replaceChildren();if(!guestMessages.length){const e=document.createElement('p');e.className='guestbook-empty';e.textContent='一张小小明信片，收藏此刻的心情。';list.append(e);}for(const m of [...guestMessages].reverse()){const card=document.createElement('article');card.className='guest-entry';card.dataset.border=['airmail','lace','flowers','pink'].includes(m.border)?m.border:'pink';const name=document.createElement('strong');name.textContent='From '+m.name;const date=document.createElement('time');const d=new Date(m.date);date.textContent=Number.isNaN(d.getTime())?'':d.toLocaleDateString();const message=document.createElement('p');message.textContent=m.text;card.append(name,date,message);if(typeof m.art==='string'&&m.art.startsWith('data:image/png;base64,')){const img=document.createElement('img');img.src=m.art;img.alt='手绘和贴纸明信片：'+m.text;message.hidden=true;card.append(img);}list.append(card);}}
function openGuestbook(object){loadGuestbook();renderGuestbook();guestbookDialog.querySelector('.guest-status').textContent='';revealDetail(guestbookDialog,object);}
function postcardArtwork(){const out=document.createElement('canvas'),rect=postcardPaper.getBoundingClientRect(),scale=680/rect.width;out.width=680;out.height=Math.round(rect.height*scale);const c=out.getContext('2d');c.fillStyle='#fffaf0';c.fillRect(0,0,out.width,out.height);c.fillStyle='#806379';c.font=(24*scale)+'px "RoomPaper",RoomChinese,cursive';c.fillText(roomTranslate('Hello, little world! ♡'),24*scale,55*scale);c.font=(18*scale)+'px "RoomPaper",RoomChinese,cursive';const field=guestbookDialog.querySelector('textarea'),fr=field.getBoundingClientRect();let y=(fr.top-rect.top+24)*scale,line='';for(const ch of field.value){if(ch==='\n'||c.measureText(line+ch).width>fr.width*scale){c.fillText(line,(fr.left-rect.left)*scale,y);y+=32*scale;line=ch==='\n'?'':ch;}else line+=ch;}c.fillText(line,(fr.left-rect.left)*scale,y);const dr=postcardCanvas.getBoundingClientRect();c.drawImage(postcardCanvas,(dr.left-rect.left)*scale,(dr.top-rect.top)*scale,dr.width*scale,dr.height*scale);c.font=(38*scale)+'px "Segoe UI Emoji"';c.textAlign='center';c.textBaseline='middle';for(const t of postcardStickers)c.fillText(t.symbol,t.x*out.width/100,t.y*out.height/100);return out.toDataURL('image/png');}
guestbookDialog.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const text=guestbookDialog.querySelector('textarea').value.trim(),name=guestbookDialog.querySelector('#guest-name').value.trim()||roomTranslate('访客'),status=guestbookDialog.querySelector('.guest-status');if(!text&&!postcardStrokes.length&&!postcardStickers.length){status.textContent='写句话、画一笔，或贴上你喜欢的小贴纸吧。';return;}loadGuestbook();if(guestMessages.length>=100){status.textContent='当前浏览器已经收藏了 100 张明信片。';return;}const next=[...guestMessages,{name:name.slice(0,40),text:text.slice(0,1000),date:new Date().toISOString(),border:postcardPaper.dataset.border,art:postcardStrokes.length||postcardStickers.length?postcardArtwork():null}];try{localStorage.setItem(guestbookKey,JSON.stringify(next));guestMessages=next;renderGuestbook();guestbookDialog.querySelector('textarea').value='';postcardStrokes=[];postcardStickers=[];selectedSticker=null;stickerLayer.replaceChildren();redrawPostcard();status.textContent='明信片已收藏在当前浏览器 ♡';}catch{status.textContent='浏览器存储空间不足或不可用，作品仍在这里，请保留后再试。';}});

const linksDialog=document.createElement('dialog');linksDialog.id='links-reader';linksDialog.className='room-detail';linksDialog.setAttribute('aria-label','项目与个人主页');linksDialog.innerHTML='<div class="detail-top"><button class="links-back" aria-label="返回项目图标">←</button><span>Projects & links</span><a class="resource-open" target="_blank" rel="noopener noreferrer">打开原页面 ↗</a><button class="detail-close" aria-label="关闭项目窗口">×</button></div><div class="links-content"></div>';document.body.appendChild(linksDialog);
function renderLinks(index){const body=linksDialog.querySelector('.links-content'),heading=linksDialog.querySelector('.detail-top span'),out=linksDialog.querySelector('.resource-open');body.replaceChildren();linksDialog.dataset.resource=index===undefined?'':String(index);if(index===undefined){heading.textContent='Projects & links';out.hidden=true;const grid=document.createElement('div');grid.className='links-grid';roomLinks.forEach((r,i)=>{const button=document.createElement('button');button.className='link-card';const icon=document.createElement('span');icon.className='link-symbol';icon.style.background=r.color;icon.style.color='#6b5481';const brand=document.createElement('img');brand.src=desktopIcons[r.id];brand.alt='';brand.style.cssText='width:44px;height:44px';icon.style.background='transparent';icon.append(brand);const title=document.createElement('strong');title.textContent=r.name;const desc=document.createElement('span');desc.textContent=r.description;button.append(icon,title,desc);button.addEventListener('click',()=>renderLinks(i));grid.append(button);});body.append(grid);return;}const r=roomLinks[index];heading.textContent=r.name;out.hidden=!r.url;if(r.url)out.href=r.url;const preview=document.createElement('div');preview.className='resource-preview';if(r.kind==='email'){const card=document.createElement('div');card.className='email-card';const img=document.createElement('img');img.src=desktopIcons.email;img.style.cssText='width:70px;margin:0 auto 22px';const title=document.createElement('h2');title.textContent='Let’s keep in touch';const address=document.createElement('p');address.textContent=r.description;const link=document.createElement('a');link.href=r.url;link.className='link-action';link.textContent='Email me ↗';card.append(img,title,address,link);preview.append(card);}else if(r.embed&&r.url){const frame=document.createElement('iframe');frame.title=r.name;frame.setAttribute('sandbox','allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox');frame.referrerPolicy='no-referrer';frame.src=r.url;preview.append(frame);}else if(r.preview){const link=document.createElement('a');link.href=r.url;link.target='_blank';link.rel='noopener noreferrer';link.setAttribute('aria-label','打开 '+r.name+' 原页面');const img=document.createElement('img');img.src=r.preview;img.alt=r.name+' 主页预览';link.append(img);preview.append(link);const caption=document.createElement('div');caption.className='resource-caption';caption.textContent='页面预览 · 点击图片打开原页面';preview.append(caption);}body.append(preview);}
function openLinks(object,index){renderLinks(index);revealDetail(linksDialog,object);}
linksDialog.querySelector('.links-back').addEventListener('click',()=>renderLinks());
for(const dialog of [guestbookDialog,linksDialog]){dialog.querySelector('.detail-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close();});dialog.addEventListener('close',()=>{document.body.style.cursor='grab';if(dialog===linksDialog&&!dialog.open)dialog.querySelector('.links-content').replaceChildren();});}

const roomPickCache=new WeakMap();function interactiveAt(e){if(roomPickCache.has(e))return roomPickCache.get(e);const value=uncachedInteractiveAt(e);roomPickCache.set(e,value);return value;}function uncachedInteractiveAt(e){const exact=directInteractiveAt(e);if(exact)return exact;if(e.pointerType!=='touch'&&!matchMedia('(pointer:coarse)').matches)return null;const rect=renderer.domElement.getBoundingClientRect();let closest=null,best=22;for(const root of [...speakerControls,pullCord,printSwitch,garlandSwitch]){let candidate=null;root.traverse(o=>{if(o.isMesh&&(o.userData.lightSwitch||o.userData.musicAction)&&!candidate)candidate=o;});if(!candidate)continue;const p=new THREE.Box3().setFromObject(candidate).getCenter(new THREE.Vector3()).project(camera);if(p.z>1||p.z< -1)continue;const x=(p.x+1)*rect.width/2+rect.left,y=(1-p.y)*rect.height/2+rect.top,d=Math.hypot(x-e.clientX,y-e.clientY);if(d<best){const visible=directInteractiveAt({clientX:x,clientY:y});if(visible&&(candidate.userData.lightSwitch?visible.userData.lightSwitch===candidate.userData.lightSwitch:visible.userData.musicAction===candidate.userData.musicAction)){best=d;closest=visible;}}}return closest;}
