function scenePoint(e){const r=renderer.domElement.getBoundingClientRect();navigationRay.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);return navigationRay.intersectObjects(scene.children,true).find(h=>h.object.visible&&!h.object.userData.hint&&!(h.object.userData.wall&&h.object.material.opacity<.45)&&h.object!==studioGround&&!(h.object.material?.transparent&&h.object.material.opacity<.35));}
