// Exactly one randomly selected interactive object receives a soft hint at a time.
const hintTargets=[],hintMap=new Map();scene.traverse(o=>{const d=o.userData;let key=null,targetObject=o;if(d.lightSwitch){key='switch'+d.lightSwitch;}else if(d.piano){key='piano';targetObject=piano;}else if(d.girl){key='girl';targetObject=girl;}else if(d.chair){key='chair';targetObject=chair;}else if(d.bunny){key='bunny';targetObject=bunny;}else if(d.drawerIndex!==undefined){key='drawer'+d.drawerIndex;targetObject=deskDrawers[d.drawerIndex];}else if(d.publication!==undefined){key='book'+d.publication;}else if(d.experience!==undefined){key='experience'+d.experience;}else if(d.certificate!==undefined){key='certificate'+d.certificate;}else if(d.awardIndex!==undefined){key='award'+d.awardIndex;}else if(d.curtain){key='curtains';}else if(d.holodata){key='holodata';}else if(d.guestbook){key='guestbook';}else if(d.resource!==undefined){key='resource'+d.resource;}else if(d.links){key='links';}if(key&&!hintMap.has(key)){hintMap.set(key,true);hintTargets.push({key,object:targetObject});}});
const hintCanvas=document.createElement('canvas');hintCanvas.width=hintCanvas.height=128;const hc=hintCanvas.getContext('2d'),hg=hc.createRadialGradient(64,64,27,64,64,63);hg.addColorStop(0,'rgba(250,217,255,0)');hg.addColorStop(.40,'rgba(255,230,177,.06)');hg.addColorStop(.67,'rgba(239,192,255,.40)');hg.addColorStop(1,'rgba(249,225,255,0)');hc.fillStyle=hg;hc.fillRect(0,0,128,128);const hintSprite=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(hintCanvas),transparent:true,depthWrite:false,depthTest:false,blending:THREE.AdditiveBlending,opacity:0}));hintSprite.userData.hint=true;hintSprite.raycast=()=>{};hintSprite.renderOrder=20;scene.add(hintSprite);let hintElapsed=0,hintBag=[],hintCurrent=null,menuHint=null;
function updateInteractionHint(dt){hintElapsed+=dt;if(menuHint){hintCurrent=menuHint;hintElapsed=1.5;}if(!hintCurrent||hintElapsed>4.5){hintElapsed=0;if(!hintBag.length)hintBag=hintTargets.slice().sort(()=>Math.random()-.5);hintCurrent=hintBag.pop();}hintSprite.visible=!document.querySelector('dialog[open]')&&pointers.size===0;if(!hintCurrent)return;const bounds=new THREE.Box3().setFromObject(hintCurrent.object),size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3());hintSprite.position.copy(center);const radius=THREE.MathUtils.clamp(Math.max(size.x,size.y,size.z)*1.55,.32,2.8);hintSprite.scale.set(radius,radius,1);hintSprite.material.opacity=Math.sin(Math.PI*Math.min(1,hintElapsed/4.5))*.58;}

