function syncVisibleViewport(){const vv=window.visualViewport;document.documentElement.style.setProperty('--app-height',(vv?.height||innerHeight)+'px');document.documentElement.style.setProperty('--viewport-top',(vv?.offsetTop||0)+'px');}syncVisibleViewport();window.visualViewport?.addEventListener('resize',syncVisibleViewport);window.visualViewport?.addEventListener('scroll',syncVisibleViewport);
document.addEventListener('focusin',e=>{if(e.target.matches('input,textarea,select')&&matchMedia('(pointer:coarse)').matches)setTimeout(()=>e.target.scrollIntoView({block:'nearest'}),250);});
// Fit the complete room to the available aspect ratio, preserving the user's zoom on rotation.
function roomFitDistance(){let lo=10,hi=88;const saved=distance,savedYaw=yaw,savedPitch=pitch,savedTarget=target.clone();yaw=.69;pitch=.64;target.set(1.15,2.05,1);for(let n=0;n<18;n++){distance=(lo+hi)/2;updateCamera();camera.updateMatrixWorld();let fits=true;for(const x of [-4.3,7])for(const y of [-.4,6.2])for(const z of [-4.35,6.8]){const p=new THREE.Vector3(x,y,z).project(camera);if(Math.abs(p.x)>.91||Math.abs(p.y)>.90)fits=false;}if(fits)hi=distance;else lo=distance;}distance=saved;yaw=savedYaw;pitch=savedPitch;target.copy(savedTarget);updateCamera();return hi;}
let previousFitDistance=roomFitDistance();distance=previousFitDistance;updateCamera();
let lastTouchTap=null;renderer.domElement.addEventListener('pointerup',e=>{if(e.pointerType!=='touch'||pointers.size>1||interactiveAt(e))return;const now=performance.now();if(lastTouchTap&&now-lastTouchTap.time<320&&Math.hypot(e.clientX-lastTouchTap.x,e.clientY-lastTouchTap.y)<22){focusObject(e);lastTouchTap=null;}else lastTouchTap={time:now,x:e.clientX,y:e.clientY};});

const selectedFontStyle=document.createElement('style');selectedFontStyle.textContent=`body{font-family:'Segoe UI','RoomChinese',sans-serif}#experience-reader,#experience-reader h2,#experience-reader .experience-role,#experience-reader .experience-date,.postcard-paper,.postcard-paper h2,.guest-entry,.guest-entry strong,.guest-entry p,.guestbook-empty{font-family:'RoomPaper','RoomChinese',cursive;font-weight:400;font-synthesis:none}#guestbook-reader .postcard-paper input,#guestbook-reader .postcard-paper textarea,#guestbook-reader .postcard-paper label{font-family:'RoomPaper','RoomChinese',cursive;font-weight:400;font-synthesis:none}#guestbook-reader .postcard-paper textarea{line-height:1.9;background:transparent}dialog button,dialog select,.guestbook-note,.guest-status,.postcard-tools,.publication-caption,.publication-venue,.publication-authors,.detail-top,.resource-caption{font-family:'Segoe UI','RoomChinese',sans-serif}#experience-reader li{line-height:1.9}#experience-reader h2{line-height:1.5}@media(max-width:760px){#experience-reader .experience-body{font-size:18px}#guestbook-reader .postcard-paper textarea{font-size:19px}}`;document.head.append(selectedFontStyle);

const controlsHelp=document.createElement('details');controlsHelp.id='room-controls';controlsHelp.innerHTML='<summary>操作说明 <span aria-hidden="true">?</span></summary><div class="controls-copy"><p class="mouse-help">左键拖动：旋转视角<br>右键 / Shift＋拖动：平移<br>滚轮：缩放<br>双击物体：拉近查看</p><p class="touch-help">单指拖动：旋转视角<br>双指拖动：平移<br>双指捏合 / 张开：缩放</p><p>点击书本、贴纸、显示器等可互动。<br>拖动椅子：地毯内移动<br>轻点椅子：旋转 45°<br>灯串墙壁开关：切换闪烁 / 关闭<br>落地灯拉绳、打印机按钮：开关灯<br>乐器：演奏与音符 · 曲谱：选曲<br>音响顶部从左到右：开关、下一首、音量 −、音量 +<br>墙上黑胶：播放你的歌曲 · 曲谱内唱片盒：选曲与许可<br>窗景：轻点拉近，拖动画面观景<br>点击钢琴：飘出小音符</p><button type="button">回到全景</button></div>';document.body.append(controlsHelp);controlsHelp.querySelector('button').onclick=()=>{harbourInspect=false;harbourManual.set(0,0);yaw=.69;pitch=.64;target.set(1.15,2.05,1);grabPoint=null;distance=roomFitDistance();previousFitDistance=distance;updateCamera();};
const controlsStyle=document.createElement('style');controlsStyle.textContent=`#room-controls{position:fixed;z-index:8;left:max(14px,env(safe-area-inset-left));bottom:max(14px,env(safe-area-inset-bottom));max-width:min(310px,calc(100vw - 28px));box-sizing:border-box;border:1px solid #ddd1e4;background:#fffaf3ed;border-radius:14px;color:#67556f;box-shadow:0 5px 22px #5b45621a;font:15px/1.8 'Segoe UI','RoomChinese',sans-serif;cursor:auto}#room-controls summary{list-style:none;cursor:pointer;min-height:44px;padding:9px 15px;box-sizing:border-box;display:flex;gap:15px;align-items:center;justify-content:space-between}#room-controls summary::-webkit-details-marker{display:none}#room-controls summary span{border:1px solid #c2aace;border-radius:50%;width:22px;height:22px;line-height:22px;text-align:center;font:16px/22px 'RoomPaper',sans-serif}.controls-copy{padding:0 17px 15px;max-height:55dvh;overflow:auto}.controls-copy p{margin:0 0 12px}.controls-copy button{min-height:44px;padding:7px 17px;border:1px solid #cfbcd9;border-radius:20px;background:#ede2f3;color:#67556f;font:inherit;cursor:pointer;touch-action:manipulation}.touch-help{display:none}@media(pointer:coarse){.touch-help{display:block}.mouse-help{display:none}#room-controls{font-size:14px;left:max(10px,env(safe-area-inset-left));bottom:max(10px,env(safe-area-inset-bottom))}}`;document.head.append(controlsStyle);
const animationClock=new THREE.Clock();updateCamera();renderer.setAnimationLoop(now=>{if(document.hidden)return;const panelOpen=!!document.querySelector('dialog[open]');if(panelOpen&&roomIdleDialog)return;roomIdleDialog=panelOpen;const frameInterval=roomTouchDevice?(pointers.size?1000/60:1000/30):1000/60;if(now-roomLastFrameAt<frameInterval-1)return;roomLastFrameAt=now;const frameStart=performance.now();const dt=Math.min(animationClock.getDelta(),.05),goal=curtainClosed?1:0;if(curtainProgress!==goal){curtainProgress=THREE.MathUtils.clamp(curtainProgress+Math.sign(goal-curtainProgress)*dt/1.05,0,1);shapeCurtains();}animatePublicationBooks(dt);animateRabbit(dt);animatePianoNotes(dt);animateDrawers(dt);updateNightMode();animatePcRainbow(dt);animateRoomDevices(dt);updateCamera();updateWallVisibility(dt);updateInteractionHint(dt);renderHarbourPortal();if(now-roomShadowAt>(roomTouchDevice?150:80)){renderer.shadowMap.needsUpdate=true;roomShadowAt=now;}renderer.render(scene,camera);window.__roomPerformance.renderedFrames++;const spent=performance.now()-frameStart;if(roomTouchDevice&&++roomMeasuredFrames%90===0){if(roomSlowFrames>25&&renderer.getPixelRatio()>.8)renderer.setPixelRatio(Math.max(.8,renderer.getPixelRatio()-.15));roomSlowFrames=0;}if(spent>25)roomSlowFrames++;});
window.__sceneReady=true;

