const experiencePhotoStyle=document.createElement('style');experiencePhotoStyle.textContent=`
#experience-reader{inset:0!important;translate:none!important;margin:auto!important;width:min(1320px,96vw)!important;max-width:none!important;max-height:94vh!important;height:fit-content!important;overflow:visible!important;display:none;filter:none;padding:0;border:0}
#experience-reader[open]{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:34px;align-items:center}
#experience-reader .experience-paper{grid-column:2;grid-row:1;filter:drop-shadow(0 10px 18px #24183133);min-width:0}
#experience-reader .experience-body{max-height:70vh;padding:30px 38px 20px}
#experience-reader .experience-tape{display:none}
.experience-album{grid-column:1;grid-row:1;min-width:0;padding:28px 25px 12px;box-sizing:border-box;color:#624c68;font-family:RoomPaper,RoomChinese,cursive}
.photo-stack{position:relative;isolation:isolate;width:100%;height:min(58vh,590px);touch-action:pan-y;outline-offset:12px}
.memory-photo{position:absolute;inset:0;margin:0;padding:13px 13px 65px;background:#fffaf0;box-shadow:2px 12px 26px #251a3638;border:1px solid #d8cbbc;box-sizing:border-box;border-radius:2px 6px 3px 4px;transform:rotate(-2deg)}
.memory-photo img{width:100%;height:100%;object-fit:contain;background:#f0e9e1;display:block;user-select:none;-webkit-user-drag:none}
.memory-photo[data-layer="1"]{transform:translate(13px,9px) rotate(3deg);z-index:-1;background:#f1e1e8}
.memory-photo[data-layer="2"]{transform:translate(-9px,16px) rotate(-5deg);z-index:-2;background:#e2e9dc}
.memory-photo[data-layer="0"]::before{content:'';position:absolute;width:100px;height:31px;background:#edd0aebd;top:-15px;left:38%;transform:rotate(8deg);clip-path:polygon(2% 0,98% 4%,95% 18%,100% 32%,96% 51%,100% 74%,96% 100%,2% 96%,5% 70%,0 52%,4% 28%)}
.memory-photo figcaption{position:absolute;bottom:9px;left:16px;right:16px;text-align:center;font-size:17px;line-height:1.35;min-height:42px;display:grid;place-content:center;overflow-wrap:anywhere}
.photo-navigation{display:flex;justify-content:center;align-items:center;gap:20px;margin-top:34px}.photo-navigation button{min-width:48px;min-height:48px;border:1px solid #c5aeba;background:#fff8ed;border-radius:48% 53% 45% 51%;color:#735777;font:28px RoomPaper,cursive;cursor:pointer;box-shadow:1px 3px 0 #b9a7bd45}.photo-navigation button:focus-visible{outline:3px solid #8873b3;outline-offset:3px}.photo-navigation button:disabled{opacity:.3;cursor:default}.photo-count{font-size:18px;min-width:60px;text-align:center}
@media(max-width:760px){#experience-reader[open]{display:flex;flex-direction:column;gap:15px;width:calc(100vw - 16px)!important;max-height:calc(var(--app-height) - 20px)!important;overflow:auto!important;margin:max(8px,env(safe-area-inset-top)) auto!important;inset:var(--viewport-top) 0 auto!important;overscroll-behavior:contain}#experience-reader .experience-paper{order:2;width:100%;flex-shrink:0}#experience-reader .experience-body{max-height:none!important;padding:30px 27px 15px!important}#experience-reader .experience-album{order:1;width:100%;padding:36px 27px 6px;flex-shrink:0}#experience-reader .photo-stack{height:clamp(280px,48vh,460px)}#experience-reader .memory-photo{padding:10px 10px 67px}#experience-reader .memory-photo figcaption{font-size:16px}#experience-reader .photo-navigation{margin-top:28px}#experience-reader .detail-close{position:fixed;top:9px!important;right:12px!important;background:#fff8edf2!important;border-radius:50%!important;z-index:10;width:44px;height:44px}}
@media(prefers-reduced-motion:reduce){.memory-photo{animation:none!important}}
`;document.head.append(experiencePhotoStyle);
const experienceAlbum=document.createElement('section');experienceAlbum.className='experience-album';experienceAlbum.setAttribute('aria-label','工作照片 / Work photos');experienceAlbum.innerHTML='<div class="photo-stack" tabindex="0" aria-roledescription="carousel"></div><nav class="photo-navigation" aria-label="照片翻页"><button type="button" class="photo-prev" aria-label="上一张 / Previous photo">←</button><span class="photo-count" aria-live="polite"></span><button type="button" class="photo-next" aria-label="下一张 / Next photo">→</button></nav>';experienceDialog.prepend(experienceAlbum);
const photoPositions=new Map();let activePhotoExperience=0;
function renderExperiencePhotos(index){activePhotoExperience=index;const photos=experiences[index].photos,at=(photoPositions.get(index)||0)%Math.max(1,photos.length),stack=experienceAlbum.querySelector('.photo-stack');stack.replaceChildren();experienceAlbum.hidden=!photos.length;if(!photos.length)return;for(let layer=Math.min(2,photos.length-1);layer>=0;layer--){const p=photos[(at+layer)%photos.length],figure=document.createElement('figure');figure.className='memory-photo';figure.dataset.layer=layer;figure.setAttribute('aria-hidden',String(layer!==0));const img=document.createElement('img');img.src=p.src;img.alt=layer===0?(experienceLanguage==='zh'?p.caption:p.captionEn):'';img.draggable=false;img.decoding='async';const caption=document.createElement('figcaption');caption.textContent=experienceLanguage==='zh'?p.caption:p.captionEn;figure.append(img,caption);stack.append(figure);}experienceAlbum.querySelector('.photo-count').textContent=(at+1)+' / '+photos.length;for(const b of experienceAlbum.querySelectorAll('button'))b.disabled=photos.length<2;}
function turnExperiencePhoto(delta){const index=activePhotoExperience,n=experiences[index].photos.length;if(n<2)return;photoPositions.set(index,((photoPositions.get(index)||0)+delta+n)%n);renderExperiencePhotos(index);if(!matchMedia('(prefers-reduced-motion:reduce)').matches)experienceAlbum.querySelector('[data-layer="0"]').animate([{opacity:.35,transform:'translateX('+delta*22+'px) rotate('+delta*5+'deg)'},{opacity:1,transform:'rotate(-2deg)'}],{duration:260,easing:'ease-out'});}
experienceAlbum.querySelector('.photo-prev').onclick=()=>turnExperiencePhoto(-1);experienceAlbum.querySelector('.photo-next').onclick=()=>turnExperiencePhoto(1);experienceAlbum.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();turnExperiencePhoto(e.key==='ArrowLeft'?-1:1);}});let photoTouch=null;const photoStack=experienceAlbum.querySelector('.photo-stack');photoStack.addEventListener('pointerdown',e=>{photoTouch={id:e.pointerId,x:e.clientX,y:e.clientY};});photoStack.addEventListener('pointerup',e=>{if(photoTouch?.id===e.pointerId){const dx=e.clientX-photoTouch.x,dy=e.clientY-photoTouch.y;if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy)*1.3)turnExperiencePhoto(dx<0?1:-1);}photoTouch=null;});photoStack.addEventListener('pointercancel',()=>photoTouch=null);

experienceDialog.append(experienceDialog.querySelector('.detail-close'));const albumFix=document.createElement('style');albumFix.textContent='#experience-reader .experience-paper{box-sizing:border-box}#experience-reader>.detail-close{width:44px;height:44px;min-height:44px;min-width:44px;top:12px;right:12px;z-index:20;background:#fff8edf2;border-radius:50%}@media(max-width:760px){#experience-reader{overflow-x:hidden!important}#experience-reader>.detail-close{position:fixed!important;top:12px!important;right:18px!important}}';document.head.append(albumFix);

