const musicRack=new THREE.Group();piano.add(musicRack);box(2.92,.10,.48,'#d3b58f',0,4.75,-.18,musicRack,.02);for(const x of [-1.05,1.05]){box(.06,.46,.06,'gold',x,4.49,-.31,musicRack);line([[x,4.70,-.30],[x,4.37,.10]],'gold',.018,musicRack);}
function makeStringInstrument(x,kind){const g=new THREE.Group();musicRack.add(g);g.position.set(x,3.12,.10);g.rotation.z=kind==='ukulele'?-.10:.09;const wood=kind==='ukulele'?'#d5a16d':'#d9c7e9';if(kind==='ukulele'){ball(.29,.32,.10,wood,0,.21,0,g);ball(.23,.25,.10,wood,0,.55,0,g);ball(.10,.10,.012,'#594839',0,.53,.106,g);}else{box(.44,.78,.15,wood,0,.38,0,g,.08);box(.25,.42,.02,'#f3f1ef',0,.39,.091,g,.04);for(const y of [.30,.52])box(.22,.05,.04,'#777182',0,y,.12,g,.005);ball(.038,.038,.022,'gold',.15,.18,.10,g);}box(.12,.84,.08,'#b6885f',0,1.12,0,g,.015);box(.18,.25,.09,wood,0,1.64,0,g,.02);box(.18,.045,.035,'#735645',0,.22,.13,g,.005);for(let i=0;i<(kind==='ukulele'?4:6);i++){const sx=(i-((kind==='ukulele'?4:6)-1)/2)*.018;line([[sx,.23,.15],[sx,1.69,.065]],'#e6dbcd',.0025,g);}for(let i=0;i<9;i++)box(.12,.008,.009,'#e5d2bb',0,.82+i*.07,.047,g);for(const side of [-1,1])for(let i=0;i<2;i++)ball(.035,.023,.025,'gold',side*.12,1.57+i*.10,0,g);line([[x,4.75,0],[x,4.64,.14],[x,4.58,.12]],'gold',.018,musicRack);g.traverse(o=>{if(o.isMesh)o.userData.musicAction=kind;});hintTargets.push({key:kind,object:g});return g;}
const ukulele=makeStringInstrument(-.72,'ukulele'),easyGuitar=makeStringInstrument(.72,'guitar');
const musicSpeaker=new THREE.Group();piano.add(musicSpeaker);musicSpeaker.position.set(0,2.49,-.393);box(1.12,.58,.40,'#e2d4bd',0,.29,0,musicSpeaker,.04);const grille=canvasMat((c,w,h)=>{c.fillStyle='#695e54';c.fillRect(0,0,w,h);c.strokeStyle='#cdbca2';c.lineWidth=1;for(let x=0;x<w;x+=6){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let y=0;y<h;y+=6){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}c.fillStyle='#fff4d9';c.font='italic 32px RoomPaper';c.textAlign='center';c.fillText('Marshall',w/2,h*.60);},360,160);const speakerFace=plane(1.02,.43,grille,0,.29,.211,musicSpeaker);const speakerPower=box(.15,.055,.13,'#594c40',-.39,.63,0,musicSpeaker,.018);speakerPower.rotation.z=-.16;speakerPower.userData.musicAction='power';const speakerNext=cyl(.073,.073,.05,'gold',-.13,.62,0,musicSpeaker);speakerNext.userData.musicAction='next';const speakerQuieter=cyl(.073,.073,.05,'gold',.13,.62,0,musicSpeaker);speakerQuieter.userData.musicAction='volume-down';const speakerLouder=cyl(.073,.073,.05,'gold',.39,.62,0,musicSpeaker);speakerLouder.userData.musicAction='volume-up';const musicLED=ball(.014,.008,.014,new THREE.MeshStandardMaterial({color:'#a7bfaa',emissive:'#9effc8',emissiveIntensity:0}),-.49,.602,0,musicSpeaker);const speakerControls=[speakerPower,speakerNext,speakerQuieter,speakerLouder];for(const [i,text]of ['开关','下一首','音量 −','音量 +'].entries()){const m=canvasMat((c,w,h)=>{c.clearRect(0,0,w,h);c.fillStyle='#594c40';c.font='24px RoomChinese';c.textAlign='center';c.fillText(text,w/2,30);},160,42);m.transparent=true;const label=plane(.24,.063,m,-.39+i*.26,.543,.214,musicSpeaker);label.userData.musicAction=speakerControls[i].userData.musicAction;} hintTargets.push({key:'music-speaker',object:musicSpeaker});
let roomMuted=false,roomMasterGain=null;
let roomAudio=null,musicTimer=null,musicTick=0,musicTrack=0,musicPower=false,scorePlaying=false,musicNodes=new Set();const backgroundTitles=['Morning postcards','Little sunshine','Weekend atelier'];
function ensureRoomAudio(){if(!roomAudio){roomAudio=new (window.AudioContext||window.webkitAudioContext)();roomMasterGain=roomAudio.createGain();roomMasterGain.gain.value=roomMuted?0:1;roomMasterGain.connect(roomAudio.destination);}if(roomAudio.state==='suspended')roomAudio.resume();return roomAudio;}
function soundNote(midi,kind='piano',when=0,length=.6,volume=.12,bus='effect'){const ac=ensureRoomAudio(),t=ac.currentTime+when,f=440*2**((midi-69)/12),gain=ac.createGain();gain.connect(roomMasterGain);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(volume,t+.006);gain.gain.exponentialRampToValueAtTime(.0001,t+length);const harmonics=kind==='piano'?[1,.36,.13]:kind==='ukulele'?[1,.5,.22,.09]:[1,.32,.25,.12,.06];harmonics.forEach((amp,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.type=kind==='guitar'&&i===0?'triangle':'sine';o.frequency.value=f*(i+1);g.gain.value=amp/(kind==='guitar'?2:1);o.connect(g);g.connect(gain);o.start(t);o.stop(t+length+.03);const item={o,g,gain,bus};musicNodes.add(item);o.onended=()=>{o.disconnect();g.disconnect();musicNodes.delete(item);};});setTimeout(()=>gain.disconnect(),(when+length+.1)*1000);}
function stopAudioBus(bus){for(const item of musicNodes)if(item.bus===bus){try{item.o.stop();}catch{}musicNodes.delete(item);}}
