const pianoLibrary=[{id:'elise',title:'致爱丽丝',en:'Für Elise',source:'https://www.mutopiaproject.org/cgibin/piece-info.cgi?id=931',notes:embeddedPianoSequences.elise},{id:'butterfly',title:'梁祝',en:'The Butterfly Lovers',notes:null},{id:'campanella',title:'钟',en:'La Campanella',source:'https://bitmidi.com/la-campanella-mid-1',notes:embeddedPianoSequences.campanella},{id:'clouds',title:'彩云追月',en:'Colourful Clouds Chasing the Moon',notes:null}];
const musicBook=document.createElement('dialog');musicBook.id='music-book';musicBook.innerHTML='<button class="music-close" aria-label="关闭曲谱">×</button><h2>我的钢琴曲谱</h2><p>My piano collection</p><div class="music-pages"></div><p class="music-status" aria-live="polite"></p><button class="score-stop">停止钢琴曲</button>';document.body.append(musicBook);const ms=document.createElement('style');ms.textContent='#music-book{width:min(700px,calc(100vw - 36px));max-height:calc(100dvh - 36px);box-sizing:border-box;overflow:auto;border:0;border-radius:4px 15px 8px 5px;background:#fff6e6;color:#65516c;padding:28px;font-family:RoomPaper,RoomChinese,cursive;box-shadow:0 20px 80px #24183060}#music-book::backdrop{background:#342a3b50}#music-book h2{font-weight:500;margin:8px 0}.music-pages{display:grid;grid-template-columns:1fr 1fr;gap:18px}.music-piece{padding:20px 15px;background:repeating-linear-gradient(#fffdf6 0 27px,#ddd0bc 28px,#fffdf6 29px 35px);border:1px solid #d7c6ae;box-shadow:2px 4px 0 #e4d3bf;transform:rotate(-1deg)}.music-piece:nth-child(even){transform:rotate(1deg)}.music-piece h3{font-size:23px;margin:0 0 8px}.music-piece button,.score-stop{min-height:44px;padding:8px 18px;border:1px solid #c9b4c4;border-radius:18px;background:#f0e2ed;color:#62486a;font:inherit;cursor:pointer}.music-piece button:disabled{opacity:.6;cursor:default}.music-piece a{display:block;font-size:13px;color:#806c90;margin-top:10px}.music-close{position:sticky;top:0;float:right;width:44px;height:44px;border:0;border-radius:50%;font-size:28px;background:#eee0e7;color:#6d526c;cursor:pointer}.music-status{min-height:24px}@media(max-width:540px){#music-book{padding:20px}.music-pages{grid-template-columns:1fr}.music-piece{padding:16px}}';document.head.append(ms);
let scoreTimer=null,scoreStart=0,scoreIndex=0,scoreNotes=[],scoreNotePulse=0;
for(const piece of pianoLibrary){const page=document.createElement('section');page.className='music-piece';const h=document.createElement('h3');h.textContent=piece.title;const sub=document.createElement('p');sub.textContent=piece.en;const play=document.createElement('button');play.textContent=piece.notes?'播放 / Play':'待添加音源';play.disabled=!piece.notes;play.onclick=()=>playPianoScore(piece);page.append(h,sub,play);if(piece.source){const a=document.createElement('a');a.href=piece.source;a.target='_blank';a.rel='noopener';a.textContent='乐曲来源 / Source';page.append(a);}musicBook.querySelector('.music-pages').append(page);}
musicBook.querySelector('.music-close').onclick=()=>musicBook.close();musicBook.querySelector('.score-stop').onclick=()=>stopPianoScore();musicBook.addEventListener('click',e=>{if(e.target===musicBook){const r=musicBook.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)musicBook.close();}});
const sheetMesh=piano.children.find(o=>o.isMesh&&o.material===score);sheetMesh.userData.musicAction='scores';hintTargets.push({key:'scorebook',object:sheetMesh});
const musicBookCover=canvasMat((c,w,h)=>{c.fillStyle='#fff9ed';c.fillRect(0,0,w,h);c.textAlign='center';c.fillStyle='#715c73';c.font='29px RoomChinese';c.fillText('钢琴曲谱',w/2,42);c.font='22px RoomChinese';['致爱丽丝 · 梁祝','钟 · 彩云追月'].forEach((t,i)=>c.fillText(t,w/2,87+i*42));for(let j=0;j<5;j++)c.fillRect(24,162+j*8,w-48,1);c.font='26px serif';c.fillText('♪   ♫   ♪',w/2,193);},320,260);sheetMesh.material=musicBookCover;

