const recordingAssets=[{"id":"bg0","title":"Carefree","kind":"background","src":"assets/web/51d6889e000fdd9a.mp3","credit":"Kevin MacLeod (incompetech.com)","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1400037"},{"id":"bg1","title":"Life of Riley","kind":"background","src":"assets/web/dc8fadc545d1e83f.mp3","credit":"Kevin MacLeod (incompetech.com)","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1400054"},{"id":"bg2","title":"Wallpaper","kind":"background","src":"assets/web/3f297e263c48c91e.mp3","credit":"Kevin MacLeod (incompetech.com)","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","source":"https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1100843"},{"id":"elise","title":"致爱丽丝","kind":"score","src":"assets/web/5c9c38d3891621e9.mp3","credit":"Ludwig van Beethoven · piano: V. Gao","license":"CC0 / Public domain","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/","source":"https://commons.wikimedia.org/wiki/File:FurElise.ogg"},{"id":"campanella","title":"钟","kind":"score","src":"assets/web/d85396c71e725fc3.mp3","credit":"Franz Liszt · piano: Romuald Greiss (2000)","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Liszt-La_Campanella-Greiss.ogg"},{"id":"qinggui","title":"情归","kind":"record","src":"assets/web/cf4da7d16fc1483b.mp3","cover":"data:image/webp;base64,"},{"id":"yueluo","title":"月落听风","kind":"record","src":"assets/web/6400ead642ebe331.mp3","cover":"data:image/webp;base64,"}];
