const roomRecordingPlayer=new Audio();roomRecordingPlayer.preload='metadata';roomRecordingPlayer.volume=.50;let activeRecording=null,recordingResume=null;
const recordingTracks=recordingAssets.filter(t=>t.kind==='background');backgroundTitles.splice(0,backgroundTitles.length,...recordingTracks.map(t=>t.title));
function recordingStatus(text){musicBook.querySelector('.music-status').textContent=text;recordStatus.textContent=text;}
function playRecording(track,kind=track.kind){closeOnlineScore(false);roomRecordingPlayer.pause();clearInterval(musicTimer);musicTimer=null;clearInterval(scoreTimer);scoreTimer=null;stopAudioBus('background');stopAudioBus('score');activeRecording={track,kind};scorePlaying=kind==='score';musicPower=true;roomRecordingPlayer.src=track.src;roomRecordingPlayer.loop=kind==='background';roomRecordingPlayer.play().then(()=>recordingStatus('正在播放 · '+track.title)).catch(()=>recordingStatus('点击播放重试 · '+track.title));musicLED.material.emissiveIntensity=1.7;speakerPower.rotation.z=.16;if(scorePlaying)scoreTimer=setInterval(()=>{if(!roomRecordingPlayer.paused)emitPianoNotes();},950);}
function startBackground(){if(!musicPower){roomRecordingPlayer.pause();musicLED.material.emissiveIntensity=0;speakerPower.rotation.z=-.16;return;}if(scorePlaying)return;playRecording(recordingTracks[musicTrack],'background');}
function stopPianoScore(resume=true){if(onlineScoreActive){closeOnlineScore(resume);return;}clearInterval(scoreTimer);scoreTimer=null;roomRecordingPlayer.pause();scorePlaying=false;stopAudioBus('score');recordingStatus('已停止 / Stopped');if(resume&&musicPower){if(recordingResume){const r=recordingResume;recordingResume=null;playRecording(r.track,r.kind);}else startBackground();}}
function playPianoScore(piece){const track=recordingAssets.find(t=>t.id===piece.id);if(!track)return;recordingResume=musicPower&&activeRecording&&activeRecording.kind!=='score'?activeRecording:null;playRecording(track,'score');}
roomRecordingPlayer.addEventListener('ended',()=>{if(activeRecording?.kind==='score')stopPianoScore(true);else{musicPower=false;musicLED.material.emissiveIntensity=0;recordingStatus('播放结束');}});roomRecordingPlayer.addEventListener('error',()=>recordingStatus('音频未能加载，请重新点击播放'));
function musicAction(action){if(action==='power'&&onlineScoreActive){closeOnlineScore(false);musicPower=true;}if(action==='volume-down'||action==='volume-up'){roomRecordingPlayer.volume=Math.max(0,Math.min(1,Math.round((roomRecordingPlayer.volume+(action==='volume-up'?.1:-.1))*10)/10));recordingStatus('音量 / Volume · '+Math.round(roomRecordingPlayer.volume*100)+'%');return;}if(action==='scores'){musicBook.showModal();return;}if(action==='records'){recordDialog.showModal();return;}if(action.startsWith('record:')){recordingResume=null;playRecording(recordingAssets.find(t=>t.id===action.slice(7)),'record');return;}if(action==='power'){musicPower=!musicPower;if(!musicPower){roomRecordingPlayer.pause();clearInterval(scoreTimer);scoreTimer=null;scorePlaying=false;recordingResume=null;stopAudioBus('background');stopAudioBus('score');musicLED.material.emissiveIntensity=0;speakerPower.rotation.z=-.16;recordingStatus('音响已关闭 / Power off');}else if(activeRecording)playRecording(activeRecording.track,activeRecording.kind);else startBackground();}else if(action==='next'){scorePlaying=false;recordingResume=null;musicTrack=(musicTrack+1)%recordingTracks.length;musicPower=true;startBackground();}else emitInstrument(action);}
