function startRabbitRun(){if(rabbitRunning)return;refreshRoomColliders();const from=new THREE.Vector3(bunny.position.x,0,bunny.position.z);for(let attempt=0;attempt<16;attempt++){const dest=attempt===0&&Math.random()<.20?rabbitHome.clone():new THREE.Vector3(-1.7+Math.random()*5.4,0,.1+Math.random()*5.65);if(from.distanceTo(dest)<.75||navigationBlocked(dest.x,dest.z,.32,.85,bed))continue;const route=planRoomRoute(from,dest,.32,.85,bed);if(!route.length)continue;rabbitRoute=route;rabbitRunning=true;rabbitState='walk';rabbitRunTime=0;return;}rabbitWait=2+Math.random()*3;rabbitState='idle';}
function animateRabbit(dt){rabbitTime+=dt;const step=Math.min(dt,.05);if(rabbitRunning){rabbitRunTime+=step;if(roomCollisionDirty)refreshRoomColliders();const goal=rabbitRoute[0];if(!goal){rabbitRunning=false;rabbitState=Math.random()<.50?'lie':'idle';rabbitWait=rabbitState==='lie'?5+Math.random()*8:2+Math.random()*4;}else{const d=new THREE.Vector3(goal.x-bunny.position.x,0,goal.z-bunny.position.z),length=d.length();if(length<.035)rabbitRoute.shift();else{d.normalize();const move=Math.min(length,step*.57),x=bunny.position.x+d.x*move,z=bunny.position.z+d.z*move;if(navigationBlocked(x,z,.32,.85,bed)){rabbitRunning=false;rabbitRoute=[];rabbitState='idle';rabbitWait=1;}else{bunny.position.x=x;bunny.position.z=z;const angle=Math.atan2(d.x,d.z);bunny.rotation.y+=Math.atan2(Math.sin(angle-bunny.rotation.y),Math.cos(angle-bunny.rotation.y))*Math.min(1,step*9);}}}}else{rabbitWait-=step;if(rabbitWait<=0)startRabbitRun();}
rabbitLie=THREE.MathUtils.damp(rabbitLie,rabbitState==='lie'?1:0,4,step);const hop=rabbitRunning?Math.abs(Math.sin(rabbitRunTime*8)):0;const homeDistance=Math.hypot(bunny.position.x-rabbitHome.x,bunny.position.z-rabbitHome.z),cushion=1-THREE.MathUtils.smoothstep(homeDistance,0,.60);bunny.scale.set(.68*(1+.08*rabbitLie),.68*(1-.28*rabbitLie),.68*(1+.15*rabbitLie));bunny.position.y=-.135+.28*cushion+.045*hop+.05*rabbitLie+Math.sin(rabbitTime*2.2)*.003;bunny.rotation.x=rabbitRunning?.025*Math.sin(rabbitRunTime*16):0;for(const f of rabbitFeet){f.o.position.y=f.y+.018*hop;f.o.position.z=f.z+.035*Math.sin(rabbitRunTime*16+(f.z<0?Math.PI:0))*(rabbitRunning?1:0)+rabbitLie*.04;}for(const e of rabbitEars){e.o.rotation.x=e.x+.50*rabbitLie+(rabbitRunning?.07*hop:.025*Math.sin(rabbitTime*3));e.o.rotation.z=e.z+.02*Math.sin(rabbitTime*4);}rabbitShadow.visible=cushion<.85;rabbitShadow.position.set(bunny.position.x,.035,bunny.position.z);rabbitShadow.material.opacity=.7-.14*hop;}

