// Horizontal neon sign mounted flush against the left wall above the bookcase.
const studyNeon=group(-4.045,4.72,-1.12,Math.PI/2);studyNeon.name='Wall-mounted study neon';
const neonBack=box(3.22,.90,.035,new THREE.MeshStandardMaterial({color:'#423b4b',roughness:.88,metalness:0}),0,0,0,studyNeon,.012);
// A coarse LED matrix: visible circular pixels, no bloom, halo or point light.
const ledMask=document.createElement('canvas');ledMask.width=128;ledMask.height=28;const ledMaskContext=ledMask.getContext('2d',{willReadFrequently:true});
const ledReducedMotion=matchMedia('(prefers-reduced-motion:reduce)');let ledLastFrame=-1;
const ledColours=['#e5a3c3','#b5a0dc','#d9d1e2','#9acbb0','#dec58e','#9bbfd6'];
function drawStudyLED(c,w,h){const m=ledMaskContext;m.clearRect(0,0,128,28);m.fillStyle='#fff';m.textAlign='center';m.textBaseline='middle';m.font=roomLanguage==='zh'?'19px RoomChinese':'15px RoomPaper';m.fillText(roomLanguage==='zh'?'Kino的微光书房':"Kino’s Glow Study",64,14,112);let pixels=m.getImageData(0,0,128,28),left=128,right=-1,top=28,bottom=-1;for(let y=0;y<28;y++)for(let x=0;x<128;x++)if(pixels.data[(y*128+x)*4+3]>100){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}const dx=Math.round((127-left-right)/2),dy=Math.round((27-top-bottom)/2);m.clearRect(0,0,128,28);m.putImageData(pixels,dx,dy);studyNeon.userData.textBounds={left:left+dx,right:right+dx,top:top+dy,bottom:bottom+dy};const data=m.getImageData(0,0,128,28).data;const phase=ledReducedMotion.matches?0:Math.floor(performance.now()/700);c.fillStyle='#302b38';c.fillRect(0,0,w,h);for(let y=0;y<28;y++)for(let x=0;x<128;x++){const border=(y===1||y===26)&&x>1&&x<126||(x===2||x===125)&&y>1&&y<26;const on=data[(y*128+x)*4+3]>100;let colour='#3f3848';if(on||border){const index=(Math.floor(x/18)+phase+(border?2:0))%6;colour=ledColours[index];}c.fillStyle=colour;c.globalAlpha=border&&!ledReducedMotion.matches?((Math.floor(x/8)+Math.floor(y/4)+phase)%3===0?.50:.85):1;c.beginPath();c.arc((x+.5)*w/128,(y+.5)*h/28,Math.min(w/128,h/28)*.34,0,Math.PI*2);c.fill();}c.globalAlpha=1;}
const neonFaceMaterial=canvasMat(drawStudyLED,1024,224);neonFaceMaterial.toneMapped=false;
const neonFace=plane(3.08,.76,neonFaceMaterial,0,0,.045,studyNeon);neonFace.castShadow=false;
for(const x of [-1.57,1.57])for(const y of [-.40,.40])ball(.012,.012,.006,'#8d8097',x,y,.026,studyNeon);
neonFace.onBeforeRender=()=>{const frame=ledReducedMotion.matches?0:Math.floor(performance.now()/140);if(frame===ledLastFrame)return;ledLastFrame=frame;drawStudyLED(neonFaceMaterial.map.image.getContext('2d'),1024,224);neonFaceMaterial.map.needsUpdate=true;};

// Pastel illustration derived from the Bennelong apartment reference below.
// Source: https://www.morton.com.au/lease/nsw/sydney-city/sydney/residential/unit/8593362
// Wider camera-responsive framing, direct drag, and subtle shader water/cloud motion.
const harbourPhoto=new THREE.TextureLoader().load('data:image/webp;base64,');harbourPhoto.colorSpace=THREE.SRGBColorSpace;harbourPhoto.wrapS=harbourPhoto.wrapT=THREE.ClampToEdgeWrapping;harbourPhoto.repeat.set(.82,.62);harbourPhoto.offset.set(.01,.17);view.map=harbourPhoto;view.needsUpdate=true;
