scene.traverse(o=>{if(o.isMesh&&o.geometry?.type==='SphereGeometry'&&Math.abs(o.position.x-3.76)<.001&&Math.abs(o.position.y-4.44)<.001&&Math.abs(o.position.z+4.035)<.001)o.visible=false;});
let harbourFrame=0,harbourDrag=null,harbourInspect=false;const harbourManual=new THREE.Vector2();function focusHarbour(){harbourInspect=true;if(curtainClosed)curtainClosed=false;yaw=.02;pitch=.10;distance=Math.max(6.2,4/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*camera.aspect*.9));target.set(4.45,4.15,-4.27);updateCamera();}
// A wide painted panorama: camera movement changes the crop substantially, without detaching landmarks.
const harbourMotion=matchMedia('(prefers-reduced-motion: reduce)');
const harbourReference=new THREE.Vector2((camera.position.x-4.45)/Math.max(2,camera.position.z+4.27),(camera.position.y-4.15)/Math.max(2,camera.position.z+4.27));
const harbourUniforms={time:{value:0},motion:{value:harbourMotion.matches?0:1}};
harbourPhoto.repeat.set(.78,.78);harbourPhoto.offset.set(.11,.11);
view.onBeforeCompile=shader=>{shader.uniforms.harbourTime=harbourUniforms.time;shader.uniforms.harbourMotion=harbourUniforms.motion;shader.fragmentShader='uniform float harbourTime; uniform float harbourMotion;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>',`#ifdef USE_MAP
 vec2 harbourUV=vMapUv;
 float sea= (1.0-smoothstep(.46,.51,harbourUV.y))*(1.0-smoothstep(mix(.34,.73,clamp(harbourUV.y/.5,0.,1.))-.025,mix(.34,.73,clamp(harbourUV.y/.5,0.,1.))+.025,harbourUV.x));
 float clouds=smoothstep(.60,.80,harbourUV.y);
 harbourUV.x+=harbourMotion*(sea*.0016*sin(harbourUV.y*130.+harbourTime*.65)+clouds*.0025*sin(harbourTime*.10));
 harbourUV.y+=harbourMotion*sea*.0008*sin(harbourUV.x*95.+harbourTime*.48);
 vec4 sampledDiffuseColor=texture2D(map,harbourUV);
 sampledDiffuseColor.rgb*=1.0+harbourMotion*sea*.012*sin(harbourUV.y*190.+harbourTime*.65);
 diffuseColor*=sampledDiffuseColor;
#endif`);};view.customProgramCacheKey=()=> 'pastel-harbour-motion-v1';view.needsUpdate=true;
function renderHarbourPortal(){const d=Math.max(2,camera.position.z+4.27),rx=(camera.position.x-4.45)/d-harbourReference.x,ry=(camera.position.y-4.15)/d-harbourReference.y;harbourPhoto.offset.set(THREE.MathUtils.clamp(.11+.105*Math.tanh(rx*1.7)+harbourManual.x,0,.22),THREE.MathUtils.clamp(.11+.09*Math.tanh(ry*1.8)+harbourManual.y,0,.22));harbourUniforms.time.value=performance.now()*.001;harbourUniforms.motion.value=harbourMotion.matches?0:1;harbourFrame++;}


// Batch fixed siblings by material. Original meshes remain as exact picking and collision proxies.
function batchRoomStatics(){scene.updateMatrixWorld(true);const parents=[];scene.traverse(o=>{if(o.children.length)parents.push(o);});const protectedRoots=[pc,printer,bunny,windowAssembly,musicSpeaker];let saved=0;
for(const parent of parents){if(protectedRoots.some(root=>ancestorIs(parent,root)))continue;const buckets=new Map();for(const o of parent.children){if(!o.isMesh||!o.visible||o.children.length||o.userData.wall||!o.geometry.attributes.normal||!o.geometry.attributes.uv||Array.isArray(o.material)||o.material.transparent||o.material.clippingPlanes||o===hintSprite||o.geometry.morphAttributes.position)continue;const key=o.material.uuid+'/'+o.castShadow+'/'+o.receiveShadow;const list=buckets.get(key)||[];list.push(o);buckets.set(key,list);}
for(const list of buckets.values()){if(list.length<3)continue;const geometries=list.map(o=>{o.updateMatrix();const g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();return g.applyMatrix4(o.matrix);});const g=new THREE.BufferGeometry();for(const name of ['position','normal','uv']){const size=geometries[0].attributes[name].itemSize,total=geometries.reduce((n,a)=>n+a.attributes[name].array.length,0),data=new Float32Array(total);let offset=0;for(const geo of geometries){data.set(geo.attributes[name].array,offset);offset+=geo.attributes[name].array.length;}g.setAttribute(name,new THREE.BufferAttribute(data,size));}g.computeBoundingBox();g.computeBoundingSphere();const batch=new THREE.Mesh(g,list[0].material);batch.name='Static room batch';batch.castShadow=list[0].castShadow;batch.receiveShadow=list[0].receiveShadow;batch.userData.renderBatch=true;batch.matrixAutoUpdate=false;batch.raycast=(ray,hits)=>{for(const original of list)if(original.visible)original.raycast(ray,hits);};for(const o of list){o.layers.set(1);o.matrixAutoUpdate=false;}parent.add(batch);geometries.forEach(a=>a.dispose());saved+=list.length-1;}}
window.__roomBatchSavings=saved;roomCollisionDirty=true;}
batchRoomStatics();
// Touch devices use one softer, smaller shadow map and fewer decorative point lights.
